// ---------------------------------------------------------------- numerics
function rng(seed){let a=seed>>>0;return()=>{a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}}
function gauss(r){let u=0,v=0;while(u===0)u=r();v=r();return Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*v)}
function zeros(n,m){return Array.from({length:n},()=>new Float64Array(m))}
function eigSym(A0){ // Jacobi; returns {val desc, vec columns}
  const n=A0.length,A=A0.map(r=>Float64Array.from(r)),V=zeros(n,n);for(let i=0;i<n;i++)V[i][i]=1;
  for(let sweep=0;sweep<60;sweep++){let off=0;for(let p=0;p<n;p++)for(let q=p+1;q<n;q++)off+=A[p][q]*A[p][q];if(off<1e-22)break;
    for(let p=0;p<n;p++)for(let q=p+1;q<n;q++){if(Math.abs(A[p][q])<1e-300)continue;const th=(A[q][q]-A[p][p])/(2*A[p][q]);const t=Math.sign(th||1)/(Math.abs(th)+Math.sqrt(th*th+1));const c=1/Math.sqrt(t*t+1),s=t*c;
      for(let k=0;k<n;k++){const akp=A[k][p],akq=A[k][q];A[k][p]=c*akp-s*akq;A[k][q]=s*akp+c*akq}
      for(let k=0;k<n;k++){const apk=A[p][k],aqk=A[q][k];A[p][k]=c*apk-s*aqk;A[q][k]=s*apk+c*aqk}
      for(let k=0;k<n;k++){const vkp=V[k][p],vkq=V[k][q];V[k][p]=c*vkp-s*vkq;V[k][q]=s*vkp+c*vkq}}}
  const idx=[...Array(n).keys()].sort((i,j)=>A[j][j]-A[i][i]);
  return{val:idx.map(i=>A[i][i]),vec:idx.map(i=>V.map(r=>r[i]))};}
function dot(a,b){let s=0;for(let i=0;i<a.length;i++)s+=a[i]*b[i];return s}
function subAngle(U,V){ // largest principal angle (deg) between spans of column lists U,V (same k)
  const k=U.length;const M=zeros(k,k);for(let i=0;i<k;i++)for(let j=0;j<k;j++)M[i][j]=dot(U[i],V[j]);
  const G=zeros(k,k);for(let i=0;i<k;i++)for(let j=0;j<k;j++){let s=0;for(let r=0;r<k;r++)s+=M[r][i]*M[r][j];G[i][j]=s}
  const e=eigSym(G).val;const smin=Math.sqrt(Math.max(0,Math.min(1,e[e.length-1])));return Math.acos(smin)*180/Math.PI}
function vecAngle(a,b){return Math.acos(Math.min(1,Math.abs(dot(a,b))/Math.sqrt(dot(a,a)*dot(b,b))))*180/Math.PI}
function randOrth(n,r){const Q=[];for(let i=0;i<n;i++){let v=Float64Array.from({length:n},()=>gauss(r));for(const q of Q){const d=dot(v,q);for(let k=0;k<n;k++)v[k]-=d*q[k]}const L=Math.sqrt(dot(v,v));Q.push(v.map(x=>x/L))}return Q}
function symFrom(Q,lam){const n=lam.length,A=zeros(n,n);for(let i=0;i<n;i++)for(let j=0;j<n;j++){let s=0;for(let k=0;k<n;k++)s+=Q[k][i]*lam[k]*Q[k][j];A[i][j]=s}return A}
function covHalf(Q,lam,N,r){const n=lam.length,C=zeros(n,n),x=new Float64Array(n);
  for(let s=0;s<N;s++){x.fill(0);for(let k=0;k<n;k++){const z=gauss(r)*Math.sqrt(Math.max(lam[k],0));for(let i=0;i<n;i++)x[i]+=z*Q[k][i]}
    for(let i=0;i<n;i++)for(let j=i;j<n;j++)C[i][j]+=x[i]*x[j]}
  for(let i=0;i<n;i++)for(let j=i;j<n;j++){C[i][j]/=N;C[j][i]=C[i][j]}return C}

